import React,{useEffect,useState}from'react';import{supabase,authConfigured}from'./supabase';import{LayoutDashboard,Bot,Plus,Zap,Megaphone,PhoneIncoming,Users,MessageSquare,BrainCircuit,Phone,BarChart3,WalletCards,Settings,Search,Bell,BookOpen,ChevronDown,ArrowUpRight,Clock3,CheckCircle2,Activity,CalendarCheck,Workflow,Headphones,Target,Play,ChevronRight,Sparkles,LogOut,UserRound,LifeBuoy,ShieldCheck,Sun,Moon}from'lucide-react';
